## Code Example
```javascript
// Minimal useSensorStream hook sketch
import { useEffect, useState } from 'react';
import { NativeModules, NativeEventEmitter } from 'react-native';
const { SensorModule } = NativeModules;
export function useSensorStream(rate = 100) {
  const [samples, setSamples] = useState([]);
  useEffect(() => {
    const onSample = (e) =>
      setSamples((s) => [...s, e.sample].slice(-512));
    const emitter = new NativeEventEmitter(SensorModule);
    const sub = emitter.addListener('SensorSample', onSample);
    SensorModule.start(rate);
    return () => { sub.remove(); SensorModule.stop(); };
  }, [rate]);
  return samples;
}
```

